mapper.select:
select id, actor_user_id, operation_kind, scope_id, key_hash, request_hash,
       result_id, status, created_at, expires_at
from edu_idempotency_record
where actor_user_id = #{actorUserId}
  and operation_kind = #{operationKind}
  and scope_id = #{scopeId}
  and key_hash = #{keyHash}

mapper.insert:
insert into edu_idempotency_record (
    actor_user_id, operation_kind, scope_id, key_hash, request_hash,
    result_id, status, created_at, expires_at
) values (
    #{actorUserId}, #{operationKind}, #{scopeId}, #{keyHash}, #{requestHash},
    #{resultId}, #{status}, utc_timestamp(3), #{expiresAt}
)

mapper.update:
update edu_idempotency_record
set status = 'SUCCEEDED',
    result_id = #{resultId}
where id = #{id}
